// Read-only preview of native generated bytes; no import, scene save or Play Mode.
if (!UnityEngine.Application.isBatchMode || UnityEditor.EditorApplication.isPlaying)
    throw new System.InvalidOperationException("Requires disposable batch Editor outside Play Mode.");
string DetectPipeline()
{
    var pipeline = UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline;
    return pipeline == null ? "BuiltIn" : pipeline.GetType().FullName.Contains("Universal") ? "URP" : "Other";
}
if (DetectPipeline() != "URP") throw new System.InvalidOperationException("Expected URP.");
if (UnityEngine.SystemInfo.graphicsDeviceType == UnityEngine.Rendering.GraphicsDeviceType.Null)
    throw new System.InvalidOperationException("GPU required for the native sprite preview.");
UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene);
const int width = 1600, height = 1100;
var camera = new UnityEngine.GameObject("Native sprite review camera").AddComponent<UnityEngine.Camera>();
camera.orthographic = true;
camera.orthographicSize = height / 32f;
camera.transform.position = new UnityEngine.Vector3(0, 0, -10);
camera.clearFlags = UnityEngine.CameraClearFlags.SolidColor;
camera.backgroundColor = new UnityEngine.Color(.025f, .04f, .075f);
camera.allowHDR = false; camera.allowMSAA = false;
var font = UnityEngine.Resources.GetBuiltinResource<UnityEngine.Font>("LegacyRuntime.ttf");
UnityEngine.Vector3 At(float x, float y) => new UnityEngine.Vector3((x - width / 2f) / 16f, (height / 2f - y) / 16f, 0);
void Label(string value, float x, float y, float size = .32f)
{
    var go = new UnityEngine.GameObject(value); go.transform.position = At(x, y);
    var text = go.AddComponent<UnityEngine.TextMesh>();
    text.text = value; text.font = font; text.fontSize = 32; text.characterSize = size;
    text.anchor = UnityEngine.TextAnchor.UpperLeft; text.color = new UnityEngine.Color(.7f, .82f, 1f);
    go.GetComponent<UnityEngine.MeshRenderer>().sharedMaterial = font.material;
}
void Draw(UnityEngine.Sprite sprite, float x, float y, int scale)
{
    var go = new UnityEngine.GameObject(sprite.name);
    go.transform.position = At(x, y); go.transform.localScale = UnityEngine.Vector3.one * scale;
    var renderer = go.AddComponent<UnityEngine.SpriteRenderer>(); renderer.sprite = sprite;
}
Label("STARTER / NATIVE 48x30 / 6x + 1x / UNMODIFIED GENERATOR OUTPUT / REVIEW ONLY", 20, 12, .44f);
string root = "ArtRevamp/SFC-20260930/pilot/raw/starter";
var files = System.IO.Directory.GetFiles(root, "candidate_*.png");
System.Array.Sort(files, System.StringComparer.Ordinal);
if (files.Length != 16) throw new System.InvalidOperationException("Expected 16 candidate outputs; layout must be reviewed if count changes.");
var rows = new System.Collections.Generic.List<object>();
for (int i = 0; i < files.Length; i++)
{
    var texture = new UnityEngine.Texture2D(2, 2, UnityEngine.TextureFormat.RGBA32, false);
    if (!UnityEngine.ImageConversion.LoadImage(texture, System.IO.File.ReadAllBytes(files[i])))
        throw new System.InvalidOperationException("Cannot decode " + files[i]);
    texture.filterMode = UnityEngine.FilterMode.Point; texture.wrapMode = UnityEngine.TextureWrapMode.Clamp;
    if (texture.width != 48 || texture.height != 30)
        throw new System.InvalidOperationException("Native size mismatch: " + files[i] + " " + texture.width + "x" + texture.height);
    var colors = new System.Collections.Generic.HashSet<uint>();
    int visible = 0, partial = 0, minX = 48, minY = 30, maxX = -1, maxY = -1;
    var pixels = texture.GetPixels32();
    for (int p = 0; p < pixels.Length; p++)
    {
        var c = pixels[p]; if (c.a == 0) continue;
        visible++; if (c.a != 255) partial++;
        colors.Add(((uint)c.r << 24) | ((uint)c.g << 16) | ((uint)c.b << 8) | c.a);
        minX = System.Math.Min(minX, p % 48); maxX = System.Math.Max(maxX, p % 48);
        minY = System.Math.Min(minY, p / 48); maxY = System.Math.Max(maxY, p / 48);
    }
    var sprite = UnityEngine.Sprite.Create(texture, new UnityEngine.Rect(0, 0, 48, 30), new UnityEngine.Vector2(.5f, .5f), 16, 0, UnityEngine.SpriteMeshType.FullRect);
    sprite.name = "candidate_" + i.ToString("D2");
    int x = (i % 4) * 400, y = 60 + (i / 4) * 260;
    Draw(sprite, x + 186, y + 94, 6);
    Draw(sprite, x + 350, y + 213, 1);
    Label(i.ToString("D2") + " / " + colors.Count + " colors / " + partial + " partial-alpha", x + 20, y + 199, .29f);
    rows.Add(new { file = files[i].Replace('\\', '/'), texture.width, texture.height,
        visiblePixels = visible, visibleRgbaColors = colors.Count, partialAlphaPixels = partial,
        opaqueBoundsBottomLeft = new[] { minX, minY, maxX + 1, maxY + 1 },
        pngPostprocessed = false, paletteBudgetPass = colors.Count <= 48,
        hardAlphaPass = partial == 0, artAccepted = false });
}
var target = UnityEngine.RenderTexture.GetTemporary(width, height, 24);
var previous = UnityEngine.RenderTexture.active;
string outputRoot = System.IO.Path.GetFullPath("ArtRevamp/SFC-20260930/pilot/review");
System.IO.Directory.CreateDirectory(outputRoot);
try
{
    camera.targetTexture = target; camera.Render(); UnityEngine.RenderTexture.active = target;
    var capture = new UnityEngine.Texture2D(width, height, UnityEngine.TextureFormat.RGB24, false);
    capture.ReadPixels(new UnityEngine.Rect(0, 0, width, height), 0, 0); capture.Apply();
    System.IO.File.WriteAllBytes(System.IO.Path.Combine(outputRoot, "starter-candidates.png"), UnityEngine.ImageConversion.EncodeToPNG(capture));
    UnityEngine.Object.DestroyImmediate(capture);
}
finally
{
    camera.targetTexture = null; UnityEngine.RenderTexture.active = previous;
    UnityEngine.RenderTexture.ReleaseTemporary(target);
}
System.IO.File.WriteAllText(System.IO.Path.Combine(outputRoot, "starter-audit.json"), Newtonsoft.Json.JsonConvert.SerializeObject(new {
    kind = "Unity GPU contact sheet, not gameplay; generated bytes unmodified",
    pipeline = DetectPipeline(), ppu = 16, displayScales = new[] { 6, 1 }, candidates = rows
}, Newtonsoft.Json.Formatting.Indented));
return new { outputRoot, count = rows.Count, sceneSaved = false, assetsImported = false };
